const items = $input.all();
let allMatches = [];

for (const item of items) {
  const html = item.json.data || '';
  const matches = [...html.matchAll(/href=["'](https:\/\/ieltsmaterial\.com\/[^"']*)["']/gi)].map(m => m[1]);
  allMatches.push(...matches);
}

const excludePatterns = [
  'task-1',
  'general',
  'how-to',
  'difference-between',
  'structure-ielts',
  'writing-essay-evaluation',
  '6-secrets',
  '/category/',
  '/tag/',
  '/author/',
  'ielts-sample-essays',
  'ielts-writing-practice-test',
  '/writing/writing-task-2/',
  'recent-ielts-topics-in-writing-task-2',
  'ielts-practice-tests',
  'ielts-opinion-essay',
  'discussion-essay-topics',
  'problem-solution-essay',
  'advantage-and-disadvantage-essays',
  'direct-question-essay',
  'ielts-writing-task-2-opinion-essays'
];

const uniqueUrls = [...new Set(allMatches)].filter(url => {
  const lower = url.toLowerCase();

  for (const pat of excludePatterns) {
    if (lower.includes(pat)) return false;
  }

  const isTask2 = (
    lower.includes('writing-task-2') ||
    lower.includes('writing-2-practice-test') ||
    lower.includes('task-2') ||
    lower.includes('practice-test-17-band-8') ||
    lower.includes('practice-test-18-band-8') ||
    (lower.includes('essay') && (
      lower.includes('band-8') ||
      lower.includes('band-9') ||
      lower.includes('sample-essay') ||
      lower.includes('discussion') ||
      lower.includes('opinion') ||
      lower.includes('problem-solution')
    ))
  );

  return isTask2;
});

return uniqueUrls.map(url => ({
  json: { url }
}));

const html = $input.item.json.data || '';

const articleMatch = html.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
const rawArticle = articleMatch ? articleMatch[1] : html;

const cleanText = rawArticle
  .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;|&rsquo;|&lsquo;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

let sourceUrl = '';
try {
  sourceUrl = $('Loop Over Items').item.json.url || '';
} catch (e) {
  sourceUrl = $json.url || '';
}

return {
  json: {
    clean_article_text: cleanText,
    source_url: sourceUrl
  }
};

