const rawText = $json.response?.generations?.[0]?.[0]?.text || $json.text || '';
const cleanJson = rawText.replace(/```json\s*|```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = { raw_output: rawText, parse_error: e.message };
}

let sourceUrl = '';
try {
  sourceUrl = $('Code in JavaScript').item.json.source_url || '';
} catch (e) {
  sourceUrl = $json.source_url || '';
}

return {
  json: {
    task_type: 'Task 2',
    essay_type: parsed.essay_type || 'Opinion Essay',
    title: parsed.title || 'IELTS Writing Task 2 Essay',
    question: parsed.question || '',
    outline: parsed.outline || {},
    sample_answers: Array.isArray(parsed.sample_answers) ? parsed.sample_answers : [],
    vocabulary: Array.isArray(parsed.vocabulary) ? parsed.vocabulary : [],
    source_url: sourceUrl
  }
};
